package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.apache.commons.math.MathException;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class MathUtils_gcd_TriageGen2Test {

    @Test
    public void testGcdZeroCases() {
        // Testing (u == 0) || (v == 0) branch
        assertEquals(5, MathUtils.gcd(0, 5));
        assertEquals(5, MathUtils.gcd(5, 0));
        assertEquals(0, MathUtils.gcd(0, 0));
        assertEquals(5, MathUtils.gcd(0, -5));
        assertEquals(5, MathUtils.gcd(-5, 0));
    }

    @Test
    public void testGcdPositiveNumbers() {
        // Standard positive cases
        assertEquals(1, MathUtils.gcd(1, 1));
        assertEquals(1, MathUtils.gcd(7, 3));
        assertEquals(6, MathUtils.gcd(12, 18));
        assertEquals(10, MathUtils.gcd(100, 10));
        // Test power of 2 casting (B1)
        assertEquals(4, MathUtils.gcd(8, 12));
        assertEquals(1, MathUtils.gcd(13, 17));
    }

    @Test
    public void testGcdNegativeNumbers() {
        // The implementation makes u and v negative, so GCD should be positive
        assertEquals(1, MathUtils.gcd(-7, -3));
        assertEquals(6, MathUtils.gcd(-12, 18));
        assertEquals(6, MathUtils.gcd(12, -18));
        assertEquals(2, MathUtils.gcd(-4, -6));
    }

    @Test
    public void testGcdMixedParity() {
        // Test B2/B3/B4/B5 logic (u odd or v odd)
        // Case where u is odd
        assertEquals(1, MathUtils.gcd(3, 4));
        // Case where v is odd
        assertEquals(1, MathUtils.gcd(4, 3));
    }

    @Test
    public void testGcdLargeValues() {
        // Test near Integer boundaries
        assertEquals(1, MathUtils.gcd(Integer.MAX_VALUE, Integer.MAX_VALUE - 2));
        assertEquals(1, MathUtils.gcd(Integer.MAX_VALUE, 2));
    }

    @Test(expected = RuntimeException.class)
    public void testGcdOverflow() {
        // The code throws an exception if k reaches 31.
        // 2^31 is not representable as a positive signed 32-bit int.
        // However, the loop check k < 31 and the exception message suggest this path.
        // To trigger k=31, we need both numbers to be multiples of 2^31.
        // Since the only 32-bit int multiple of 2^31 is 0 (handled) or -2^31.
        // Let's try to trigger the overflow logic if possible.
        // Note: MathUtils.gcd(Integer.MIN_VALUE, Integer.MIN_VALUE)
        // u = -2147483648, v = -2147483648. 
        // k will increment until u and v are no longer even or k=31.
        // Because -2^31 is 1 followed by 31 zeros in binary, 
        // dividing by 2 thirty-one times will reach k=31.
        MathUtils.gcd(Integer.MIN_VALUE, Integer.MIN_VALUE);
    }

    @Test
    public void testGcdOne() {
        assertEquals(1, MathUtils.gcd(1, 1));
        assertEquals(1, MathUtils.gcd(1, -1));
        assertEquals(1, MathUtils.gcd(-1, 1));
        assertEquals(1, MathUtils.gcd(-1, -1));
    }
}
